using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Payments.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.Payments.Commands.CancelPayment;public sealed class CancelPaymentCommandHandler(IPaymentRepository repository,IApplicationDbContext db):IRequestHandler<CancelPaymentCommand,Result<PaymentDto>>{public async Task<Result<PaymentDto>>Handle(CancelPaymentCommand request,CancellationToken cancellationToken){var e=await repository.FindForUpdateAsync(request.Id,cancellationToken);if(e is null)return Result.Failure<PaymentDto>(PaymentErrors.NotFound);if(e.Status!="Draft")return Result.Failure<PaymentDto>(PaymentErrors.NotDraft);e.Cancel();await db.SaveChangesAsync(cancellationToken);return Result.Success(PaymentDto.FromEntity(e));}}
